solution.Solution.cs:
using System.Globalization;

public static class Csv
{
    public static List<string> ParseLine(string line)
    {
        var fields = new List<string>();
        var field = new StringBuilder();
        bool quoted = false;
        for (int i = 0; i < line.Length; i++)
        {
            char c = line[i];
            if (quoted)
            {
                if (c == '"' && i + 1 < line.Length && line[i + 1] == '"') { field.Append('"'); i++; }
                else if (c == '"') quoted = false;
                else field.Append(c);
            }
            else if (c == '"') quoted = true;
            else if (c == ',') { fields.Add(field.ToString()); field.Clear(); }
            else field.Append(c);
        }
        fields.Add(field.ToString());
        return fields;
    }

    public static string FormatLine(IEnumerable<string> fields) =>
        string.Join(",", fields.Select(f =>
            f.IndexOfAny([',', '"', '\n', '\r']) >= 0 ? "\"" + f.Replace("\"", "\"\"") + "\"" : f));

    public static Dictionary<string, decimal> TotalsBy(TextReader reader, string keyColumn, string valueColumn)
    {
        var header = ParseLine(reader.ReadLine() ?? "");
        int k = header.IndexOf(keyColumn), v = header.IndexOf(valueColumn);
        if (k < 0) throw new ArgumentException($"no column {keyColumn}");
        if (v < 0) throw new ArgumentException($"no column {valueColumn}");
        var totals = new Dictionary<string, decimal>();
        string? line;
        while ((line = reader.ReadLine()) != null)
        {
            if (string.IsNullOrWhiteSpace(line)) continue;
            var f = ParseLine(line);
            decimal value = decimal.Parse(f[v], NumberStyles.Number, CultureInfo.InvariantCulture);
            totals[f[k]] = totals.GetValueOrDefault(f[k]) + value;
        }
        return totals;
    }

    public static async Task<int> CopyColumnsAsync(string inputPath, string outputPath, params string[] columns)
    {
        string[] lines = await File.ReadAllLinesAsync(inputPath);
        var header = ParseLine(lines.Length > 0 ? lines[0] : "");
        int[] indexes = columns.Select(c => header.IndexOf(c) is int i and >= 0 ? i : throw new ArgumentException($"no column {c}")).ToArray();
        int rows = 0;
        await using var writer = new StreamWriter(outputPath);
        await writer.WriteLineAsync(FormatLine(columns));
        foreach (string line in lines.Skip(1))
        {
            if (string.IsNullOrWhiteSpace(line)) continue;
            var f = ParseLine(line);
            await writer.WriteLineAsync(FormatLine(indexes.Select(i => f[i])));
            rows++;
        }
        return rows;
    }
}

unitTests:
Test("parsing quoted fields", () =>
{
    CheckEq(Csv.ParseLine("a,\"b, c\",\"say \"\"hi\"\"\""), new[] { "a", "b, c", "say \"hi\"" });
    CheckEq(Csv.ParseLine("1,,3"), new[] { "1", "", "3" });
    CheckEq(Csv.ParseLine(""), new[] { "" });
    CheckEq(Csv.ParseLine("\"\""), new[] { "" });
});

Test("formatting round-trips", () =>
{
    var fields = new[] { "plain", "with, comma", "a \"quote\"", "" };
    string line = Csv.FormatLine(fields);
    CheckEq(line, "plain,\"with, comma\",\"a \"\"quote\"\"\",");
    CheckEq(Csv.ParseLine(line), fields);
});

Test("totals from any reader", () =>
{
    var csv = new StringReader("region,product,amount\nnorth,tea,2.50\nsouth,\"cake, large\",12\n\nnorth,mug,8\n");
    var totals = Csv.TotalsBy(csv, "region", "amount");
    CheckEq(totals["north"], 10.50m);
    CheckEq(totals["south"], 12m);
    CheckThrows<ArgumentException>(() => Csv.TotalsBy(new StringReader("a,b\n1,2"), "a", "price"));
});

Test("copying columns between files", () =>
{
    string dir = Path.Combine(Path.GetTempPath(), "xenon-csv-" + Guid.NewGuid().ToString("N"));
    Directory.CreateDirectory(dir);
    string input = Path.Combine(dir, "people.csv"), output = Path.Combine(dir, "names.csv");
    File.WriteAllLines(input, new[] { "id,name,city", "1,Ada,London", "2,\"Hopper, Grace\",New York", "" });
    int rows = Csv.CopyColumnsAsync(input, output, "name", "id").GetAwaiter().GetResult();
    CheckEq(rows, 2);
    CheckEq(File.ReadAllLines(output), new[] { "name,id", "Ada,1", "\"Hopper, Grace\",2" });
    CheckThrows<FileNotFoundException>(() => Csv.CopyColumnsAsync(Path.Combine(dir, "nope.csv"), output, "id").GetAwaiter().GetResult());
    Directory.Delete(dir, true);
});

